import{_ as c,C as i,o as l,c as n,aj as r,E as d,j as e,a as o}from"./chunks/framework.DkvuVDKz.js";const g=JSON.parse('{"title":"Watermark 水印","description":"","frontmatter":{},"headers":[],"relativePath":"components/watermark.md","filePath":"components/watermark.md","lastUpdated":1789238475000}'),h={name:"components/watermark.md"};function s(m,t,u,b,k,p){const a=i("XhDemo");return l(),n("div",null,[t[0]||(t[0]=r('<h1 id="watermark-水印" tabindex="-1">Watermark 水印 <a class="header-anchor" href="#watermark-水印" aria-label="Permalink to &quot;Watermark 水印&quot;">​</a></h1><p>在内容区域上重复显示文字或图片水印。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/watermark" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/watermark.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/watermark" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/watermark" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/watermark.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>为内容添加文字水印</p>',5)),d(a,{src:"watermark/01-basic"}),t[1]||(t[1]=r('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;watermark&quot;</code>：<strong><code>root</code></strong> · <code>content</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="多行水印" tabindex="-1">多行水印 <a class="header-anchor" href="#多行水印" aria-label="Permalink to &quot;多行水印&quot;">​</a></h3><p>显示归属和时间信息</p>',6)),d(a,{src:"watermark/02-multi-line"}),t[2]||(t[2]=e("h3",{id:"外观",tabindex:"-1"},[o("外观 "),e("a",{class:"header-anchor",href:"#外观","aria-label":'Permalink to "外观"'},"​")],-1)),t[3]||(t[3]=e("p",null,"设置角度、间距、字号和透明度",-1)),d(a,{src:"watermark/03-appearance"}),t[4]||(t[4]=e("h3",{id:"自定义颜色",tabindex:"-1"},[o("自定义颜色 "),e("a",{class:"header-anchor",href:"#自定义颜色","aria-label":'Permalink to "自定义颜色"'},"​")],-1)),t[5]||(t[5]=e("p",null,"设置水印前景色",-1)),d(a,{src:"watermark/04-custom-color"}),t[6]||(t[6]=r('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>标记内部数据、预览稿或样例内容。</li><li>在导出或截图内容中保留归属信息。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>水印不能替代访问控制或数据脱敏。</li><li>装饰纹理应使用背景样式。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>支持单行、多行文字和图片水印。</li><li>支持角度、间距、字号、透明度和字体配置。</li><li>水印不拦截指针事件，也不影响文本选择。</li><li>深浅主题下自动使用对应的前景色。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>可包裹<a href="./table">表格</a>、<a href="./card">卡片</a>或页面内容区。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>保持水印可见，但不要干扰正文阅读。</li><li>需要追溯时包含用户、时间或文档编号。</li><li>图片水印优先使用轮廓清晰的单色图形。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>不要把水印当作安全边界。</li><li>不要使用过高的不透明度。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-watermark&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhWatermarkContent</code> <code>XhWatermarkRoot</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/watermark.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>fontFamily</code></td><td><code>string</code></td><td></td><td>印文字用的字体，缺省 <code>sans-serif</code>。 图样是一张当遮罩用的 SVG，取不到页面里的字体，所以要在这里把字体名写全 （例如 <code>&#39;PingFang SC, sans-serif&#39;</code>）；写的字体在运行环境里不存在时由平台自己回退。</td></tr><tr><td><code>fontSize</code></td><td><code>number</code></td><td></td><td>字号，单位像素，缺省 14。</td></tr><tr><td><code>gap</code></td><td><code>number</code></td><td></td><td>两块图样之间留的空白，单位像素，缺省 24。</td></tr><tr><td><code>image</code></td><td><code>string</code></td><td></td><td>印在文字上方的图片，只收 <code>data:image/</code> 开头的内联图片。 图样是当遮罩用的，遮罩只取图样的透明度：印出来是这张图的剪影，颜色仍由 <code>--xh-watermark-fg</code> 给。外部地址一律不收——SVG 当图片用时取不到外部资源， 收了也印不出东西。</td></tr><tr><td><code>imageSize</code></td><td><code>WatermarkImageSize</code></td><td></td><td>图片的像素尺寸，缺省 64 × 64。</td></tr><tr><td><code>opacity</code></td><td><code>number</code></td><td></td><td>印子的深浅，0 到 1，缺省 0.15。</td></tr><tr><td><code>rotate</code></td><td><code>number</code></td><td></td><td>倾斜角度，单位度，缺省 -22。</td></tr><tr><td><code>text</code></td><td><code>string | string[]</code></td><td></td><td>水印文字。给数组就是多行，单个字符串里的换行同样断行； 去掉空白行——它只让图样长高，印不出任何东西。</td></tr></tbody></table><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>lines</code></td><td><code>readonly string[]</code></td><td>归一化后的文字行；没有可印的文字时是空数组。</td></tr><tr><td><code>tile</code></td><td><code>WatermarkTile</code></td><td>图样尺寸，即平铺步距；没有图样时宽高都是 0。</td></tr><tr><td><code>image</code></td><td><code>string</code></td><td>图样的 data URI；没有图样时是空串。</td></tr><tr><td><code>state</code></td><td><code>WatermarkState</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/watermark.css</code> 使用 <code>[data-scope=&quot;watermark&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；缺省来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>缺省来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-watermark-fg</code></td><td><code>root</code></td><td><code>background-color</code></td><td><code>state=ready</code></td><td><code>--xh-fg-muted</code></td><td>watermark 的 root 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-watermark-image</code></td><td><code>root</code></td><td><code>-webkit-mask-image</code><br><code>mask-image</code></td><td><code>state=ready</code></td><td><code>none</code></td><td>watermark 的 root 部件 -webkit-mask-image、mask-image 覆盖槽。</td></tr><tr><td><code>--xh-watermark-tile</code></td><td><code>root</code></td><td><code>-webkit-mask-size</code><br><code>mask-size</code></td><td><code>state=ready</code></td><td><code>auto</code></td><td>watermark 的 root 部件 -webkit-mask-size、mask-size 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p>本组件皮肤不含过渡与关键帧，也没有脚本驱动的动效：状态一变，外观立即到位。</p>',33))])}const q=c(h,[["render",s]]);export{g as __pageData,q as default};
